import type { ImgHTMLAttributes } from "react";
import images from "../data/images.json";

type Manifest = Record<
  string,
  { width: number; height: number; srcset: string } | undefined
>;

interface Props extends ImgHTMLAttributes<HTMLImageElement> {
  src: string;
  /** How wide the image renders, e.g. "(max-width: 640px) 100vw, 50vw". */
  sizes?: string;
  /** Above-the-fold image: load at once, ahead of everything else. */
  priority?: boolean;
}

// Adds the srcset and intrinsic size generated by `npm run images`, so the
// browser picks the smallest file that fits and reserves space before it loads.
export default function ResponsiveImage({
  src,
  sizes = "100vw",
  priority = false,
  ...rest
}: Props) {
  const entry = (images as Manifest)[src];
  return (
    <img
      src={src}
      srcSet={entry?.srcset}
      sizes={entry ? sizes : undefined}
      width={entry?.width}
      height={entry?.height}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding={priority ? undefined : "async"}
      {...rest}
    />
  );
}
